#!/usr/bin/env python3
"""Authored chapter 5 selections; all formulae/coordinates derive from stated givens."""
import json, math, copy
from pathlib import Path
sqrt=math.sqrt
OUT=Path(__file__).resolve().parents[2]/'stereo-course/shestakov-yaschenko-10-11/chapters/ch5.json'
L=[]; T=[]
def fmt(x): return str(int(x)) if int(x)==x else str(round(x,10)).replace('.',',')
def vadd(a,b): return [a[i]+b[i] for i in range(3)]
def vmul(a,t): return [x*t for x in a]
def mid(a,b): return vmul(vadd(a,b),.5)
def sub(a,b): return [a[i]-b[i] for i in range(3)]
def dot(a,b): return sum(x*y for x,y in zip(a,b))
def proj(p,a,b):
 d=sub(b,a); return vadd(a,vmul(d,dot(sub(p,a),d)/dot(d,d)))
def view(m,key,label,segments=None,polygon=None,points=None):
 m['views'][key]={'label':label}
 for k,v in [('segments',segments),('polygon',polygon),('points',points)]:
  if v:m['views'][key][k]=v
 return key
def poly_model(pts,names,apex='S'):
 edges=[[names[i],names[(i+1)%len(names)]] for i in range(len(names))]+[[apex,n] for n in names]
 faces=[names]+[[apex,names[i],names[(i+1)%len(names)]] for i in range(len(names))]
 m={'points':pts,'edges':edges,'faces':faces,'labelNames':names+[apex],'views':{'neutral':{'label':'Исходная пирамида'}}}
 view(m,'base','Основание пирамиды',polygon=names)
 view(m,'face','Одна боковая грань',polygon=[apex,names[0],names[1]])
 return m
def tri(a,h,apex='S'):
 t=a*sqrt(3)/2; pts={'A':[0,0,0],'B':[a,0,0],'C':[a/2,t,0],apex:[a/2,t/3,h],'O':[a/2,t/3,0],'M':[a/2,0,0]}
 m=poly_model(pts,['A','B','C'],apex)
 view(m,'height','Высота перпендикулярна основанию',segments=[[apex,'O']],points=['O'])
 view(m,'edge','Ребро и его проекция',segments=[[apex,'A'],['A','O'],[apex,'O']],points=['O'])
 view(m,'apothem','Апофема и её проекция',segments=[[apex,'M'],['M','O'],[apex,'O']],points=['M','O'])
 return m
def square(a,h,apex='S'):
 pts={'A':[-a/2,-a/2,0],'B':[a/2,-a/2,0],'C':[a/2,a/2,0],'D':[-a/2,a/2,0],apex:[0,0,h],'O':[0,0,0],'M':[0,-a/2,0]}
 m=poly_model(pts,list('ABCD'),apex)
 view(m,'height','Высота и половина диагонали',segments=[[apex,'O'],['O','A']],points=['O'])
 view(m,'diagonal','Диагональ основания',segments=[['B','D'],['A','C']],points=['O'])
 view(m,'apothem','Высота боковой грани',segments=[[apex,'M'],['M','O'],[apex,'O']],points=['M','O'])
 return m
def hexa(a,h,apex='S',foot=None):
 pts={n:[a*math.cos(i*math.pi/3),a*math.sin(i*math.pi/3),0] for i,n in enumerate('ABCDEF')};pts['O']=[0,0,0]
 pts[apex]=[0,0,h] if foot is None else vadd(pts[foot],[0,0,h]);pts['M']=mid(pts['A'],pts['B'])
 m=poly_model(pts,list('ABCDEF'),apex)
 view(m,'height','Высота пирамиды',segments=[[apex,foot or 'O']],points=[foot or 'O'])
 view(m,'radius','Радиус описанной окружности равен стороне',segments=[['O','A'],['O','B']],points=['O'])
 view(m,'apothem','Апофема SM',segments=[[apex,'M'],['M','O']],points=['M','O'])
 return m
def rect(a,b,h,apex='S',foot=(0,0)):
 pts={'A':[0,0,0],'B':[a,0,0],'C':[a,b,0],'D':[0,b,0],apex:[foot[0],foot[1],h],'O':[foot[0],foot[1],0]}
 m=poly_model(pts,list('ABCD'),apex)
 view(m,'height','Высота к плоскости основания',segments=[[apex,'A' if foot==(0,0) else 'O']],points=['A' if foot==(0,0) else 'O'])
 return m
def st(title,prompt,explanation,reason,view='base',inp=None):
 s={'title':title,'prompt':prompt,'explanation':explanation,'reason':reason,'view':view}
 if inp:s['input']={'prompt':inp[0],'accepted':[str(inp[1])],'feedback':inp[2]}
 return s
def add(sec,lev,num,part,pages,title,text,goal,ans,steps,m,hint='',caption='',manual=False):
 acc=[str(x) for x in (ans if isinstance(ans,list) else [ans])]
 for x in acc[:]:
  if ',' in x:acc.append(x.replace(',','.'))
 a={'mode':'manual' if manual else 'exact','prompt':goal+(' Запиши доказательство и численный результат.' if manual else ' Введи точное значение без единиц; корень можно записать как sqrt(число).')}
 if not manual:a.update(accepted=list(dict.fromkeys(acc)),feedback='Проверь выбранный прямоугольный треугольник, а затем вычисления. Подсказка сохраняет твою запись.')
 L.append({'section':sec,'level':lev,'number':num,'part':part,'pages':pages,'title':title,'text':text,'goal':goal,'answer':a,'hint':hint or steps[0]['prompt'],'steps':steps,'model':m,'caption':caption or 'Модель построена по данным задачи. Вспомогательные линии появляются в соответствующем шаге; размеры не измеряй по экрану.'})
def theory(sec,title,pages,text,steps,m):
 T.append({'section':sec,'title':title,'pages':pages,'text':text,'goal':'Выбери нужное сечение, назови прямой угол и объясни, какая формула следует из него.','hint':steps[0]['prompt'],'steps':steps,'model':m,'caption':'Авторская опора к теме задачника. Численная модель иллюстрирует отношения; формулы в шагах действуют для указанных в них фигур.'})

